import subprocess
from dataclasses import dataclass
from agents import function_tool


@dataclass
class RebuildResult:
    restaurant_id: str
    service_date: str
    exit_code: int
    output: str


@function_tool
def run_table_availability_rebuild(restaurant_id: str, service_date: str) -> RebuildResult:
    proc = subprocess.run(
        ["python", "-m", "reservations.jobs.rebuild_availability", "--restaurant", restaurant_id, "--date", service_date],
        capture_output=True,
        text=True,
        timeout=300,
    )
    output = proc.stdout.strip() if proc.returncode == 0 else proc.stderr.strip()
    return RebuildResult(restaurant_id, service_date, proc.returncode, output[-2000:])

import sqlite3

DB_PATH = "/var/lib/reservations/bookings.db"


def archive_completed_reservation(reservation_id: int) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT guest_id, status FROM reservations WHERE id = ?", (reservation_id,)).fetchone()
        if row is None or row[1] != "completed":
            return {"reservation_id": reservation_id, "archived": False, "reason": "not found or not completed"}
        conn.execute("INSERT INTO reservation_history SELECT * FROM reservations WHERE id = ?", (reservation_id,))
        conn.execute("DELETE FROM reservations WHERE id = ?", (reservation_id,))
        conn.execute("UPDATE guests SET visit_count = visit_count + 1 WHERE id = ?", (row[0],))
        conn.commit()
    finally:
        conn.close()
    return {"reservation_id": reservation_id, "archived": True, "guest_id": row[0]}
